set -euo pipefail
cd /home/ubuntu/apps/travel-planner
.venv/bin/python - <<'PY'
import json,base64
from pathlib import Path
data=json.loads('{"rag/service/web/app.js": "", "rag/client/run_on_server.ps1": ""}')
for n,b in data.items():Path(n).write_bytes(base64.b64decode(b))
PY
bash rag/service/stop_retrieval_server.sh
bash rag/service/start_retrieval_server.sh
.venv/bin/python - <<'PY'
import requests
base='http://127.0.0.1:8100'
for name in ['','app.js','style.css']:
 r=requests.get(base+'/ui/'+name,timeout=10);r.raise_for_status()
print('UI assets served successfully')
print('Provider usage:',requests.get(base+'/maps/usage').json()['usage'])
PY
